use std :: sync :: LazyLock ; use forge_domain :: Template ; use handlebars :: { Handlebars , no_escape } ; use include_dir :: { Dir , include_dir } ; use serde :: Serialize ; use serde_json :: json ; use super :: * ; impl < 'a > TemplateEngine < 'a > { # [doc = " Renders a template with the provided data."] pub fn render < V : serde :: Serialize > (& self , template : impl Into < Template < V > > , data : & V ,) -> anyhow :: Result < String > { let template = template . into () ; Ok (self . handlebar . render (& template . template , data) ?) } # [doc = " Renders a template with the provided data."] pub fn render_template < V : serde :: Serialize > (& self , template : impl Into < Template < V > > , data : & V ,) -> anyhow :: Result < String > { let template = template . into () ; Ok (self . handlebar . render_template (& template . template , data) ?) } pub fn handlebar_instance () -> Handlebars < 'static > { create_handlebar () } }